#include<iostream>
using namespace std;

int fibonacci(int n) {
    if (n == 0)
        return 0;
    else if (n == 1)
        return 1;
    else
        return fibonacci(n-1) + fibonacci(n-2);
}

int main() {
    int n;
    cout << "Enter the position of the Fibonacci number: ";
    cin >> n;
    cout << "The " << n << "th Fibonacci number is: " << fibonacci(n);
    return 0;
}

#include<iostream>
using namespace std;

int tribonacci(int n) {
    if (n == 0)
        return 0;
    else if (n == 1)
        return -1;
    else if (n == 2)
        return -1;
    else {
        int a = 0, b = -1, c = -1;
        for (int i = 3; i <= n; i++) {
            int temp = a + b + c;
            a = b;
            b = c;
            c = temp;
        }
        return c;
    }
}

int main() {
    int n;
    cout << "Enter the position of the Tribonacci number: ";
    cin >> n;
    cout << "The " << n << "th Tribonacci number is: " << tribonacci(n);
    return 0;
}

